(function () {
    'use strict';
    // 酒馆助手(TH) type:script：直接运行于宿主页面上下文（可访问 $ / #send_textarea / #send_but）
    var ID = 'saulos-onboard-terminal';
    function isHost() {
        try { return !!(window.parent && window.parent.jQuery && window.parent.document && window.parent.document.getElementById('send_textarea')); }
        catch (e) { return false; }
    }
    var W = (isHost() ? window.parent : window);
    var $ = W.jQuery || (typeof jQuery !== 'undefined' ? jQuery : null);
    var doc = W.document || document;
    if (!$) { return; } // 宿主无 jQuery（非酒馆环境），静默退出
    if (doc.getElementById(ID)) { return; } // 已注入，防止重复

    // 注入面板到聊天区顶部
    var panel = $('<div id="' + ID + '" style="border:1px solid #d99a1b;border-radius:14px;background:linear-gradient(160deg,#151210,#0c0b09);padding:16px 20px;margin:10px 0;font-family:monospace;color:#e8c76a;box-shadow:0 4px 18px rgba(0,0,0,.55)"></div>');

    var hd = $('<div style="font-size:14px;font-weight:700;color:#f2c94c;border-bottom:1px solid rgba(217,154,27,.35);padding-bottom:8px;margin-bottom:10px">☢ SAUL·OS 毒师宇宙 · 沙盒身份登记终端 <span style="float:right;font-size:11px;color:#8a6d3b;font-weight:400">HEISENBERG v1.2</span></div>');
    panel.append(hd);

    // 表单容器（可编辑）
    var grid = $('<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;font-size:12px"></div>');
    var fields = [
        ['type','身份类型','穿越者'],['name','姓名','张三'],['sex','性别','男'],['age','年龄','30'],
        ['job','职业起点','自由职业'],['origin','出身','阿尔伯克基'],['trait','性格','谨慎'],
        ['goal','核心目标','白手起家'],['morality','道德底线','灰色地带'],
        ['year','时间线年份','2002'],['era','时代标签','风骚律师时代'],
        ['cash','初始资金 $','5000'],['purity','初始纯度 %','50'],['scale','初始规模','零散']
    ];
    fields.forEach(function (f) {
        var box = $('<div style="display:flex;flex-direction:column"></div>');
        box.append($('<label style="color:#d99a1b;font-size:10.5px;margin-bottom:2px"></label>').text(f[1]));
        box.append($('<input data-sf="' + f[0] + '" style="background:#060505;border:1px solid rgba(217,154,27,.3);border-radius:6px;color:#f5e6c8;padding:6px 8px;font-size:12px;font-family:inherit"></input>').val(f[2]));
        grid.append(box);
    });
    // DLC 全宽
    var dlcBox = $('<div style="display:flex;flex-direction:column;grid-column:1/-1"></div>');
    dlcBox.append($('<label style="color:#d99a1b;font-size:10.5px;margin-bottom:2px"></label>').text('DLC 玩法（逗号分隔）'));
    dlcBox.append($('<input data-sf="dlc" style="background:#060505;border:1px solid rgba(217,154,27,.3);border-radius:6px;color:#f5e6c8;padding:6px 8px;font-size:12px;font-family:inherit"></input>').val('洗衣帝国、卡特尔战争'));
    grid.append(dlcBox);
    panel.append(grid);

    // 按钮
    var btns = $('<div style="display:flex;gap:10px;margin-top:14px"></div>');
    function buildCmd() {
        function v(k, def) { var el = panel.find('[data-sf="' + k + '"]'); return (el.length && el.val() && el.val().trim()) ? el.val().trim() : def; }
        return '【毒师宇宙·沙盒 建号完成】\n'
            + '身份类型：' + v('type','穿越者') + '\n'
            + '姓名：' + v('name','张三') + '（' + v('sex','男') + '，' + v('age','30') + '岁）\n'
            + '职业起点：' + v('job','自由职业') + '\n'
            + '出身：' + v('origin','阿尔伯克基') + '\n'
            + '性格：' + v('trait','谨慎') + '\n'
            + '核心目标：' + v('goal','白手起家') + ' | 道德底线：' + v('morality','灰色地带') + '\n'
            + '时间线：' + v('year','2002') + '年（' + v('era','风骚律师时代') + '）| 初始资金：$' + v('cash','5000') + ' | 初始纯度：' + v('purity','50') + '% | 初始规模：' + v('scale','零散') + '\n'
            + 'DLC：' + v('dlc','洗衣帝国、卡特尔战争') + '\n'
            + '请根据以上信息在主世界初始化我的状态，并开启对应剧情线。';
    }
    var previewBtn = $('<button type="button" style="flex:1;border:none;border-radius:8px;padding:10px;font-size:12.5px;font-weight:700;cursor:pointer;background:rgba(217,154,27,.12);color:#e8c76a;border:1px solid rgba(217,154,27,.4)"></button>').text('预览指令');
    var sendBtn = $('<button type="button" style="flex:1;border:none;border-radius:8px;padding:10px;font-size:12.5px;font-weight:700;cursor:pointer;background:linear-gradient(180deg,#e8c76a,#d99a1b);color:#1a1206"></button>').text('生成 & 发送建号指令');
    var note = $('<div id="saulos-preview" style="display:none;margin-top:10px;padding:9px 13px;background:rgba(217,154,27,.08);border-left:3px solid #d99a1b;border-radius:6px;font-size:11px;color:#b8a268;white-space:pre-wrap;font-family:monospace"></div>');
    btns.append(previewBtn, sendBtn);
    panel.append(btns, note);

    previewBtn.on('click', function () { note.text(buildCmd()).show(); });
    sendBtn.on('click', function () {
        var cmd = buildCmd();
        var ta = doc.getElementById('send_textarea');
        if (!ta) { note.text('未检测到 #send_textarea，请手动发送：\n' + cmd).show(); return; }
        ta.value = cmd;
        ta.dispatchEvent(new Event('input', { bubbles: true }));
        ta.dispatchEvent(new Event('change', { bubbles: true }));
        var sb = doc.getElementById('send_but');
        if (sb) { try { sb.click(); } catch (e) {} }
        else { ta.focus(); }
    });

    // 挂载到宿主聊天区
    var $chat = $('#chat');
    if ($chat.length) { $chat.prepend(panel); }
    else { $('body').prepend(panel); }
})();
